const env: Record<string, string | undefined> = process.env;

export const baseURL = env.QA_AGENT_BASE_URL ?? QA.baseURL;

/** Thrown when a precondition outside the app is missing (credentials, role); reported as BLOCKED. */
export class QaBlockedError extends Error {
  constructor(message: string) {
    super(`QA_AGENT_BLOCKED: ${message}`);
    this.name = 'QaBlockedError';
  }
}

/** A run may only target an allowlisted origin, even when QA_AGENT_BASE_URL overrides the config. */
export function assertAllowedBaseURL(): void {
  const origin = new URL(baseURL).origin;
  if (!QA.allowedOrigins.includes(origin)) {
    throw new QaBlockedError(
      `base URL origin ${origin} is not in allowedOrigins (${QA.allowedOrigins.join(', ')})`,
    );
  }
}

function credentials(role: string): { username: string; password: string } {
  const key = QA.accounts[role];
  if (!key) throw new QaBlockedError(`role "${role}" has no account in the project config`);
  const prefix = `QA_AGENT_ACCOUNT_${key.toUpperCase().replace(/[^A-Z0-9]+/g, '_')}`;
  const username = env[`${prefix}_USERNAME`];
  const password = env[`${prefix}_PASSWORD`];
  if (!username || !password)
    throw new QaBlockedError(`missing ${prefix}_USERNAME / ${prefix}_PASSWORD`);
  return { username, password };
}

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Directory of cached sessions for a Playwright config file. */
export function authDirFor(configFile: string | undefined): string {
  return path.resolve(path.dirname(configFile ?? path.join(process.cwd(), 'x')), QA.authDir);
}

/** Per-role isolated browser contexts (cookies never shared between roles). */
export class Actors {
  private readonly browser: Browser;
  private readonly authDir: string;
  private readonly contexts = new Map<string, BrowserContext>();
  private readonly pages = new Map<string, Page>();
  private readonly fromCache = new Set<string>();
  /** What happened to each role's session in this test: signed-in, reused, refreshed. */
  readonly sessionEvents: string[] = [];

  constructor(browser: Browser, authDir: string) {
    this.browser = browser;
    this.authDir = authDir;
  }

  private sessionFile(role: string): string {
    return path.join(this.authDir, `${role.replace(/[^\w-]/g, '_')}.json`);
  }

  private freshSession(role: string): string | null {
    if (!QA.session.cache) return null;
    const file = this.sessionFile(role);
    const stat = fs.statSync(file, { throwIfNoEntry: false });
    return stat && Date.now() - stat.mtimeMs < QA.session.maxAgeMinutes * 60_000 ? file : null;
  }

  /** The role's context; `fresh` ignores any cached session (e.g. to test signing in). */
  async context(role: string, options: { fresh?: boolean } = {}): Promise<BrowserContext> {
    let ctx = this.contexts.get(role);
    if (!ctx) {
      assertAllowedBaseURL();
      const cached = options.fresh || role === 'anonymous' ? null : this.freshSession(role);
      ctx = await this.browser.newContext({ baseURL, ...(cached ? { storageState: cached } : {}) });
      if (cached) this.fromCache.add(role);
      this.contexts.set(role, ctx);
    }
    return ctx;
  }

  /** The role's main tab. */
  async page(role: string, options: { fresh?: boolean } = {}): Promise<Page> {
    let page = this.pages.get(role);
    if (!page) {
      page = await (await this.context(role, options)).newPage();
      this.pages.set(role, page);
    }
    return page;
  }

  /** An additional tab in the same role context (shares the role's session). */
  async newTab(role: string): Promise<Page> {
    return (await this.context(role)).newPage();
  }

  /** API client sharing the role's cookies. */
  async request(role: string): Promise<APIRequestContext> {
    return (await this.context(role)).request;
  }

  async login(role: string, options: { invalidPassword?: boolean } = {}): Promise<void> {
    if (!QA.login)
      throw new QaBlockedError('the project config has no login recipe (exploration.auth)');
    const loginRe = new RegExp(`${escapeRe(QA.login.loginPath)}(\\?|#|$)`);
    const page = await this.page(role);
    if (!options.invalidPassword && this.fromCache.has(role)) {
      // Controlled refresh: reuse the cached session only if it is still accepted.
      await page.goto(QA.session.verifyPath);
      await page.waitForLoadState();
      if (!loginRe.test(page.url())) {
        this.sessionEvents.push(`${role}: reused`);
        return;
      }
      this.fromCache.delete(role);
      this.sessionEvents.push(`${role}: expired`);
    }
    const { username, password } = credentials(role);
    await page.goto(QA.login.loginPath);
    await page.getByLabel(QA.login.usernameLabel, { exact: true }).fill(username);
    await page
      .getByLabel(QA.login.passwordLabel, { exact: true })
      .fill(options.invalidPassword ? `${password}-wrong` : password);
    await page.getByRole('button', { name: QA.login.submitButton, exact: true }).click();
    await page.waitForLoadState();
    if (options.invalidPassword) return;
    await expect(page, `sign-in as ${role} must leave the login page`).not.toHaveURL(loginRe);
    this.sessionEvents.push(`${role}: signed-in`);
    if (QA.session.cache) {
      // Atomic write: parallel workers never read a half-written session file.
      fs.mkdirSync(this.authDir, { recursive: true });
      const file = this.sessionFile(role);
      const tmp = `${file}.${process.pid}.${Date.now()}.tmp`;
      await page.context().storageState({ path: tmp });
      fs.renameSync(tmp, file);
    }
  }

  async close(): Promise<void> {
    for (const ctx of this.contexts.values()) await ctx.close();
    this.contexts.clear();
    this.pages.clear();
  }

  get openContexts(): number {
    return this.contexts.size;
  }
}

/** Reset test data through the configured endpoint (globalSetup / globalTeardown). */
export async function resetTestData(): Promise<void> {
  if (!QA.resetPath) return;
  assertAllowedBaseURL();
  const res = await fetch(new URL(QA.resetPath, baseURL), { method: 'POST' });
  if (res.status >= 300)
    throw new QaBlockedError(`test data reset POST ${QA.resetPath} returned HTTP ${res.status}`);
}

/** Delete cached sessions (they hold session cookies). */
export function purgeSessions(config: FullConfig): void {
  fs.rmSync(authDirFor(config.configFile), { recursive: true, force: true });
}

let counter = 0;
const runToken = env.QA_AGENT_RUN_ID ?? Date.now().toString(36);

/** Unique, traceable test data: `QA <key> <caseId> <run>-w<worker>-<n>`. */
export function unique(caseId: string, key: string): string {
  counter += 1;
  return `QA ${key} ${caseId} ${runToken}-w${test.info().workerIndex}-${counter}`;
}

export interface Subject {
  path: string;
  id: string;
}

/** The record a form submission produced (its detail page URL). */
export function subjectOf(page: Page): Subject {
  const p = new URL(page.url()).pathname;
  return { path: p, id: p.split('/').filter(Boolean).at(-1) ?? '' };
}

export async function expectPath(page: Page, expected: string): Promise<void> {
  await expect
    .poll(() => new URL(page.url()).pathname, { message: `URL path should be ${expected}` })
    .toBe(expected);
}

/** Text check scoped to the table row that contains `anchor` when such a row exists. */
export async function expectTextNear(page: Page, anchor: string, text: string): Promise<void> {
  const row = page.getByRole('row').filter({ hasText: anchor });
  if ((await row.count()) > 0) await expect(row.first()).toContainText(text);
  else await expect(page.getByText(text, { exact: true }).first()).toBeVisible();
}

export async function apiCount(request: APIRequestContext, listPath: string): Promise<number> {
  const res = await request.get(listPath);
  expect(res.status(), `GET ${listPath}`).toBe(200);
  const body: unknown = await res.json();
  if (!Array.isArray(body)) throw new Error(`GET ${listPath} did not return a JSON array`);
  return body.length;
}

export const test = base.extend<{ actors: Actors }>({
  actors: async ({ browser }, use, testInfo) => {
    const actors = new Actors(browser, authDirFor(testInfo.config.configFile));
    try {
      await use(actors);
    } finally {
      for (const e of actors.sessionEvents)
        testInfo.annotations.push({ type: 'qa-session', description: e });
      await actors.close();
    }
  },
});

export { expect };
